<?php
class AdminNtCreatorRewardsCatalogController extends ModuleAdminController
{
    public function __construct(){parent::__construct();$this->bootstrap=true;}
    public function postProcess(){if(Tools::isSubmit('saveNtcrCatalog'))try{$type=Tools::getValue('type');if(!in_array($type,array('gift','explore'),true))throw new RuntimeException('Tür geçersiz.');$name=trim(Tools::getValue('name'));$points=(int)Tools::getValue('points');if($name===''||$points<1)throw new RuntimeException('Ad ve puan zorunludur.');$stock=Tools::getValue('stock');Db::getInstance()->insert('ntcr_catalog',array('id_shop'=>(int)$this->context->shop->id,'type'=>$type,'name'=>pSQL($name),'description'=>pSQL(Tools::getValue('description'),true),'points'=>$points,'stock'=>$stock===''?null:(int)$stock,'service_scope'=>pSQL(Tools::getValue('service_scope'),true),'min_notice_hours'=>(int)Tools::getValue('min_notice_hours',24),'slot_capacity'=>max(1,(int)Tools::getValue('slot_capacity',1)),'active'=>1,'date_add'=>date('Y-m-d H:i:s'),'date_upd'=>date('Y-m-d H:i:s')));$this->confirmations[]='Katalog öğesi eklendi.';}catch(Exception $e){$this->errors[]=$e->getMessage();}if(Tools::isSubmit('toggleNtcrCatalog')){$id=(int)Tools::getValue('id_catalog');Db::getInstance()->execute('UPDATE `'._DB_PREFIX_.'ntcr_catalog` SET active=1-active,date_upd=NOW() WHERE id_catalog='.$id.' AND id_shop='.(int)$this->context->shop->id);$this->confirmations[]='Katalog durumu değiştirildi.';}parent::postProcess();}
    public function initContent(){parent::initContent();$rows=Db::getInstance()->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_catalog` WHERE id_shop='.(int)$this->context->shop->id.' ORDER BY type,position,id_catalog DESC');$this->context->smarty->assign('ntcr_catalog',$rows);$this->content=$this->context->smarty->fetch(_PS_MODULE_DIR_.'ntcreatorrewards/views/templates/admin/catalog.tpl');$this->context->smarty->assign('content',$this->content);}
}
